<script setup lang="ts">
import {computed,ref} from 'vue'
const state=ref('idle'),size=ref('medium'),tone=ref('neutral'),runs=ref(0)
const busy=computed(()=>state.value==='loading')
const message=computed(()=>({idle:'Ready for a local simulation.',loading:'Loading sample result. Finish, fail or cancel with the controls below.',success:'Sample finished locally. Nothing saved.',error:'Sample failed locally. Retry is available.',cancelled:'Sample cancelled locally.'}[state.value]))
function start(){if(busy.value)return;runs.value++;state.value='loading'}
</script>
<template><section class="spinner-usage" aria-label="Spinner usage demonstration"><p>Fictitious manual simulation. No request, timer or server process runs.</p><div class="options"><label>Spinner size<select v-model="size"><option>small</option><option>medium</option><option>large</option></select></label><label>Spinner color<select v-model="tone"><option>neutral</option><option>accent</option></select></label></div><div class="result" :aria-busy="busy"><span v-if="busy" class="spinner" :class="[size,tone]" aria-hidden="true"></span><p>Sample result region</p></div><p role="status" aria-atomic="true">{{message}}</p><div class="actions"><button type="button" :disabled="busy" @click="start"><span v-if="busy" class="spinner small" aria-hidden="true"></span>{{busy?'Loading sample…':state==='error'?'Retry sample':'Start sample'}}</button><button type="button" :disabled="!busy" @click="state='success'">Finish sample</button><button type="button" :disabled="!busy" @click="state='error'">Fail sample</button><button type="button" :disabled="!busy" @click="state='cancelled'">Cancel sample</button><button type="button" @click="state='idle'">Reset sample</button></div><p>Local starts: {{runs}}</p></section></template>
<style scoped>
.spinner-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options,.actions{display:flex;gap:12px;flex-wrap:wrap}label{display:flex;gap:10px;align-items:center;flex-wrap:wrap}button,select{min-height:44px;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}button{display:inline-flex;align-items:center;gap:8px}button:disabled{opacity:.6;cursor:not-allowed}.result{display:flex;align-items:center;gap:12px;min-height:90px}.spinner{box-sizing:border-box;display:inline-block;flex-shrink:0;width:24px;height:24px;border:3px solid var(--vp-c-divider);border-top-color:var(--vp-c-text-1);border-radius:50%;animation:guide-spin 800ms linear infinite}.spinner.small{width:16px;height:16px;border-width:2px}.spinner.large{width:36px;height:36px;border-width:4px}.spinner.accent{border-top-color:var(--vp-c-brand-1)}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:3px}@keyframes guide-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinner{animation:none!important;transform:none}}
</style>
